func localArgs(origin string) []string {
	return []string{"--terrabase-url", origin, "--auth-url", origin, "--dashboard-url", origin, "--status-url", origin, "--orchestrator-url", "", "--region", "gru-1", "--cell", "gru", "--timeout", "1s"}
}

func Run(ctx context.Context, args []string, output io.Writer) (err error) {
	out := commandio.NewWriter(output)
	defer func() { err = errors.Join(err, out.Err()) }()
	if err := ctx.Err(); err != nil {
		return err
	}
	f := flag.NewFlagSet("verify", flag.ContinueOnError)
	f.SetOutput(out)
	live := f.Bool("live", os.Getenv("TS_VERIFY_LIVE") == "1", "opt in to read-only production requests")
	region := f.String("region", env("E2E_REGION", "gru-1"), "expected cell/region")
	cell := f.String("cell", env("TS_VERIFY_CELL", "gru"), "expected controller manifest cell (distinct from TerraBase region)")
	tb := f.String("terrabase-url", env("E2E_TERRABASE_URL", "https://gru.api.terrascale.tech"), "TerraBase origin")
	auth := f.String("auth-url", env("E2E_AUTH_URL", "https://gru.auth.terrascale.tech"), "ts-auth origin")
	dash := f.String("dashboard-url", env("E2E_DASHBOARD_URL", "https://dash.terrascale.tech"), "dashboard origin")
	status := f.String("status-url", env("E2E_STATUS_URL", "https://status.terrascale.tech"), "status origin")
	orch := f.String("orchestrator-url", os.Getenv("TS_VERIFY_ORCHESTRATOR_URL"), "controller observability origin (HTTPS or loopback tunnel)")
	timeout := f.Duration("timeout", 10*time.Second, "deadline per GET")
	if err := f.Parse(args); errors.Is(err, flag.ErrHelp) {
		return nil
	} else if err != nil {
		return err
	}
	if f.NArg() != 0 || *timeout <= 0 || *region == "" || *cell == "" {
		return errors.New("verify requires no positional arguments, a region and a positive timeout")
	}
	if !*live {
		return errors.New("verify requires --live or TS_VERIFY_LIVE=1; no requests sent")
	}
	for _, origin := range []string{*tb, *auth, *dash, *status, *orch} {
		if origin != "" && !validOrigin(origin) {
			return errors.New("origins must be HTTPS (HTTP only on loopback), without credentials, query, fragment or path")
		}
	}
	v := verifier{ctx: ctx, region: *region, cell: *cell, http: &http.Client{Timeout: *timeout, CheckRedirect: func(*http.Request, []*http.Request) error { return http.ErrUseLastResponse }}}
	if *orch == "" {
		v.add("1. Orchestrator deployed and working", "UNKNOWN", "controller observability URL/token unavailable; no public controller route is assumed", "TS-484")
	} else {
		v.orchestrator(*orch)
	}
	v.health("TerraBase liveness", *tb, "/healthz", "ok", true, "TS-484, TS-486")
	// Both producer readiness probes write: TerraBase creates a scratch file;
	// ts-auth creates/reads/deletes a document. GET alone is not a read-only guarantee.
	v.add("2. Orchestrator deployed healthy TerraBase", "UNKNOWN", "liveness is reported separately; /readyz skipped (disk write); no current signed host deployment/readiness evidence", "TS-484, TS-485, TS-524")
	v.health("ts-auth liveness", *auth, "/healthz", "ok", false, "TS-487")
	v.add("3. ts-auth persists in TerraBase", "UNKNOWN", "/readyz skipped (creates/deletes storage probe documents); liveness does not establish the active store or durable records", "TS-489, TS-487, TS-525")
	v.health("Dashboard liveness", *dash, "/health/live", "ok", false, "TS-472")
	v.health("Dashboard readiness", *dash, "/health/ready", "ok", false, "TS-472")
	v.add("4. Dashboard persists in TerraBase", "UNKNOWN", "readiness only checks for a non-nil store; no evidence tying current service state to TerraBase documents", "TS-472, TS-492, TS-526")
	v.oidc(*auth)
	body, code, _, evidence := v.get(*status, "/api/v1/status", "")
	var publicStatus struct {
		Status      string    `json:"status"`
		GeneratedAt time.Time `json:"generatedAt"`
		Groups      []struct {
			Components []struct{ ID, Status string } `json:"components"`
		} `json:"groups"`
	}
	state := "PASS"
	if code != http.StatusOK || json.Unmarshal(body, &publicStatus) != nil || len(publicStatus.Groups) == 0 || publicStatus.GeneratedAt.IsZero() || publicStatus.Status == "" {
		state = "FAIL"
		evidence += "; expected timestamped status JSON with groups"
	} else {
		evidence += "; status=" + publicStatus.Status + ", generatedAt=" + publicStatus.GeneratedAt.UTC().Format(time.RFC3339) + " (observations only, not deployment/persistence proof)"
	}
	v.add("Status API response", state, evidence, "TS-497, TS-471")
	fmt.Fprintf(out, "Read-only production verification: cell=%s, region=%s, observed_at=%s\n\n", clean(*cell), clean(*region), time.Now().UTC().Format(time.RFC3339))
	fmt.Fprintln(out, "| Item | Result | Evidence | Gap tickets |\n| --- | --- | --- | --- |")
	complete := true
	for _, r := range v.rows {
		fmt.Fprintf(out, "| %s | %s | %s | %s |\n", clean(r.Item), r.Status, clean(r.Evidence), r.Tickets)
		complete = complete && r.Status == "PASS"
	}
	if !complete {
		return errors.Join(ctx.Err(), errors.New("production verification incomplete: FAIL/UNKNOWN items require gap follow-up"))
	}
	return ctx.Err()
}

func validOrigin(origin string) bool {
	u, err := url.Parse(origin)
	if err != nil || u.Hostname() == "" || u.User != nil || u.RawQuery != "" || u.ForceQuery || u.Fragment != "" || (u.Path != "" && u.Path != "/") {
		return false
	}
	return u.Scheme == "https" || (u.Scheme == "http" && (u.Hostname() == "localhost" || net.ParseIP(u.Hostname()).IsLoopback()))
}

func clean(value string) string {
	for _, name := range []string{"TS_VERIFY_ORCHESTRATOR_TOKEN", "TS_VERIFY_OIDC_JWT", "E2E_MANAGEMENT_CREDENTIAL", "E2E_API_KEY"} {
		if secret := os.Getenv(name); secret != "" {
			value = strings.ReplaceAll(value, secret, "[redacted]")
		}
	}
	value = strings.Map(func(r rune) rune {
		if r < 32 || r == 127 {
			return ' '
		}
		return r
	}, value)
	return strings.ReplaceAll(value, "|", "\\|")
}

func (v *verifier) add(item, status, evidence, tickets string) {
	v.rows = append(v.rows, row{item, status, evidence, tickets})
}

// get only requests reviewed paths, refuses redirects and never prints bodies,
// cookies, credentials, or raw upstream/network error messages.
func (v *verifier) get(origin, path, token string) ([]byte, int, http.Header, string) {
	target := strings.TrimRight(origin, "/") + path
	evidence := "GET " + target
	req, err := http.NewRequestWithContext(v.ctx, http.MethodGet, target, nil)
	if err != nil {
		return nil, 0, nil, evidence + ": invalid request"
	}
	req.Header.Set("Cache-Control", "no-cache")
	if token != "" {
		req.Header.Set("Authorization", "Bearer "+token)
	}
	res, err := v.http.Do(req)
	if err != nil {
		kind := "connection/TLS/DNS error"
		if v.ctx.Err() != nil {
			kind = "canceled"
		} else {
			var dns *net.DNSError
			if errors.As(err, &dns) {
				kind = "DNS lookup failed"
			}
			var timeout net.Error
			if errors.As(err, &timeout) && timeout.Timeout() {
				kind = "timeout"
			}
		}
		return nil, 0, nil, evidence + ": " + kind
	}
	defer res.Body.Close()
	evidence += fmt.Sprintf(": HTTP %d", res.StatusCode)
	for _, name := range []string{"X-TerraBase-Region", "X-TerraBase-Version", "X-Version", "CF-Ray"} {
		if value := res.Header.Get(name); value != "" && len(value) <= 128 {
			evidence += "; " + name + "=" + value
		}
	}
	body, err := io.ReadAll(io.LimitReader(res.Body, (1<<20)+1))
	if err != nil || len(body) > 1<<20 {
		return nil, res.StatusCode, res.Header, evidence + "; unreadable/oversized body"
	}
	return body, res.StatusCode, res.Header, evidence
}

func (v *verifier) health(item, origin, path, expected string, regional bool, tickets string) {
	body, code, headers, evidence := v.get(origin, path, "")
	var payload struct{ Status, Version, Region string }
	state := "PASS"
	if code != http.StatusOK || json.Unmarshal(body, &payload) != nil || payload.Status != expected || payload.Version == "" {
		state = "FAIL"
		evidence += "; expected versioned health JSON, status=" + expected
	} else {
		evidence += "; version=" + payload.Version
		if regional && (payload.Region != v.region || headers.Get("X-TerraBase-Region") != v.region) {
			state = "FAIL"
			evidence += "; body/header region mismatch (want " + v.region + ")"
		}
	}
	v.add(item, state, evidence, tickets)
}

func NewWriter(destination io.Writer) *Writer {
	return &Writer{destination: destination}
}

func (writer *Writer) Write(contents []byte) (int, error) {
	if writer.err != nil {
		return 0, writer.err
	}
	written, err := writer.destination.Write(contents)
	if err == nil && written != len(contents) {
		err = io.ErrShortWrite
	}
	writer.err = err
	return written, err
}

func (writer *Writer) Err() error { return writer.err }

func (v *verifier) oidc(auth string) {
	body, code, _, evidence := v.get(auth, "/.well-known/openid-configuration", "")
	var discovery struct {
		Issuer string `json:"issuer"`
		JWKS   string `json:"jwks_uri"`
	}
	state := "PASS"
	if code != 200 || json.Unmarshal(body, &discovery) != nil || !validOrigin(discovery.Issuer) || strings.TrimRight(discovery.Issuer, "/") != strings.TrimRight(auth, "/") {
		state = "FAIL"
		evidence += "; expected ts-auth issuer discovery"
	}
	if state == "PASS" {
		// Only fetch reviewed key routes from this origin. A discovery URL
		// must never direct a GET to a writing readiness/Management route.
		u, err := url.Parse(discovery.JWKS)
		origin, _ := url.Parse(auth)
		if err != nil || u.Scheme != origin.Scheme || u.Host != origin.Host || u.User != nil || u.RawQuery != "" || u.ForceQuery || u.Fragment != "" || (u.EscapedPath() != "/.well-known/jwks.json" && u.EscapedPath() != "/.well-known/jwks" && u.EscapedPath() != "/connect/jwks") {
			state = "FAIL"
			evidence += "; invalid/off-origin jwks_uri"
		} else {
			keys, status, _, detail := v.get(auth, u.EscapedPath(), "")
			evidence += "; " + detail
			var jwks struct {
				Keys []json.RawMessage `json:"keys"`
			}
			if status != 200 || json.Unmarshal(keys, &jwks) != nil || len(jwks.Keys) == 0 {
				state = "FAIL"
				evidence += "; expected non-empty JWKS"
			}
		}
	}
	v.add("OIDC discovery/nonempty JWKS retrieved", state, evidence, "TS-491, TS-487")
	// ListOrganizationsAsync calls EnsureCatalogAsync, which may initialize
	// or migrate the catalog. Neither positive nor negative auth probes can
	// safely use that handler (an auth bypass could let either reach it).
	v.add("5. TerraBase validates ts-auth user JWTs", "UNKNOWN", "Management GETs skipped (catalog initialization/migration writes); discovery/JWKS alone cannot prove JWT acceptance; needs a passive authenticated route", "TS-491, TS-519, TS-527")
}

func journalRecords(t *testing.T, entries ...Entry) []Record {
	t.Helper()
	p := newLogPipeline(t)
	path := filepath.Join(t.TempDir(), "journal.jsonl")
	file, err := os.Create(path)
	if err != nil {
		t.Fatal(err)
	}
	for _, e := range entries {
		line, err := json.Marshal(map[string]string{"_SYSTEMD_UNIT": e.Unit, "_COMM": e.Comm, "_PID": e.PID, "PRIORITY": e.Priority, "__REALTIME_TIMESTAMP": fmt.Sprint(e.At.UnixMicro()), "MESSAGE": e.Message})
		if err != nil {
			t.Fatal(err)
		}
		if _, err := fmt.Fprintln(file, string(line)); err != nil {
			t.Fatal(err)
		}
	}
	for _, invalid := range []string{`[104,105]`, `--`, ``, `{"_COMM":"invalid","MESSAGE":[104,105]}`} {
		if _, err := fmt.Fprintln(file, invalid); err != nil {
			t.Fatal(err)
		}
	}
	if err := file.Close(); err != nil {
		t.Fatal(err)
	}
	file, err = os.Open(path)
	if err != nil {
		t.Fatal(err)
	}
	defer file.Close()
	counter := NewCounter("gru", "node-a")
	var parser Parser
	scanner := bufio.NewScanner(file)
	line := 0
	for scanner.Scan() {
		entry, ok := DecodeJournal(scanner.Bytes())
		if line >= len(entries) {
			if ok {
				t.Fatalf("invalid journal line %q was accepted", scanner.Text())
			}
		} else {
			want := entries[line]
			if !ok || !entry.At.Equal(want.At.Truncate(time.Microsecond)) {
				t.Fatalf("journal entry %d timestamp = %v, decoded = %v", line, entry.At, ok)
			}
			entryFields, wantFields := entry, want
			entryFields.At, wantFields.At = time.Time{}, time.Time{}
			if entryFields != wantFields {
				t.Fatalf("journal entry %d = %+v, want %+v", line, entry, want)
			}
			if record, ok := parser.Parse(entry); ok {
				counter.Add(record)
			}
		}
		line++
	}
	if err := scanner.Err(); err != nil {
		t.Fatal(err)
	}
	for _, record := range parser.Flush() {
		counter.Add(record)
	}
	p.publish(t, p.key, counter.Flush(time.Now().UTC().Truncate(time.Minute)))
	reply := p.query(t, "limit=500")
	var records []Record
	for _, c := range reply.Classes {
		for range c.Count {
			records = append(records, Record{Service: c.Service, Level: c.Level, Component: c.Component, Message: c.Message, Example: c.Example})
		}
	}
	return records
}

func DecodeJournal(line []byte) (Entry, bool) {
	var raw struct {
		Unit     string          `json:"_SYSTEMD_UNIT"`
		Comm     string          `json:"_COMM"`
		PID      string          `json:"_PID"`
		Priority string          `json:"PRIORITY"`
		Realtime string          `json:"__REALTIME_TIMESTAMP"`
		Message  json.RawMessage `json:"MESSAGE"`
	}
	if json.Unmarshal(line, &raw) != nil {
		return Entry{}, false
	}
	var message string
	if json.Unmarshal(raw.Message, &message) != nil {
		return Entry{}, false
	}
	entry := Entry{Unit: raw.Unit, Comm: raw.Comm, PID: raw.PID, Message: message, Priority: raw.Priority}
	if micros, err := strconv.ParseInt(raw.Realtime, 10, 64); err == nil {
		entry.At = time.UnixMicro(micros)
	}
	return entry, true
}

func validLevel(level string) bool {
	return severity(level) >= 0
}

func severity(level string) int {
	for i, known := range levels {
		if known == level {
			return i
		}
	}
	return -1
}

func dotnet(pid, header, message string) []Entry {
	return []Entry{{Comm: "terrabase", PID: pid, Message: header}, {Comm: "terrabase", PID: pid, Message: "      " + message}}
}

func (p *Parser) Parse(e Entry) (Record, bool) {
	p.queue = append(p.queue, p.step(e)...)
	if len(p.queue) == 0 {
		return Record{}, false
	}
	r := p.queue[0]
	p.queue = p.queue[1:]
	return r, true
}

// Flush returns the queued records and the headers whose message never came.
func (p *Parser) Flush() []Record {
	out := p.queue
	p.queue = nil
	for pid, head := range p.held {
		out = append(out, head)
		delete(p.held, pid)
	}
	return out
}

func (p *Parser) step(e Entry) []Record {
	var out []Record
	indented := strings.HasPrefix(e.Message, " ")
	if head, ok := p.held[e.PID]; ok {
		delete(p.held, e.PID)
		if indented {
			if p.inRecord == nil {
				p.inRecord = make(map[string]bool)
			}
			p.inRecord[e.PID] = true
			head.Message, head.Example = Normalize(e.Message), example(e.Message)
			return []Record{head}
		}
		out = append(out, head)
	}
	// Exception text and stack frames are indented too; they end with the record.
	if indented && p.inRecord[e.PID] {
		return out
	}
	delete(p.inRecord, e.PID)
	if head, ok := dotnetHeader(e); ok {
		if p.held == nil {
			p.held = make(map[string]Record)
		}
		p.held[e.PID] = head
		return out
	}
	if r, ok := Classify(e); ok {
		out = append(out, r)
	}
	return out
}

func Classify(e Entry) (Record, bool) {
	if strings.TrimSpace(e.Message) == "" {
		return Record{}, false
	}
	for _, classify := range []func(Entry) (Record, bool){slogRecord, natsRecord, netbirdRecord} {
		if r, ok := classify(e); ok {
			return r, true
		}
	}
	return Record{Service: unitService(e), Level: priorityLevel(e.Priority), Message: Normalize(e.Message), Example: example(e.Message)}, true
}

// slogRecord reads record v1 and slog JSON: {"level","msg","component","error","service"}.
func slogRecord(e Entry) (Record, bool) {
	var slog struct {
		Level     string `json:"level"`
		Msg       string `json:"msg"`
		Component string `json:"component"`
		Error     string `json:"error"`
		Service   string `json:"service"`
	}
	if !strings.HasPrefix(e.Message, "{") || json.Unmarshal([]byte(e.Message), &slog) != nil || !validLevel(slog.Level) {
		return Record{}, false
	}
	message := slog.Msg
	if slog.Error != "" {
		message += ": " + slog.Error
	}
	return Record{Service: cmp.Or(slog.Service, unitService(e)), Level: slog.Level, Component: slog.Component,
		Message: Normalize(message), Example: example(e.Message)}, true
}

var (
	dotnetHeaderLine = regexp.MustCompile(`^(trce|dbug|info|warn|fail|crit): ([^\[ ]+)`)
	dotnetLevels     = map[string]string{"trce": LevelDebug, "dbug": LevelDebug, "info": LevelInfo, "warn": LevelWarn, "fail": LevelError, "crit": LevelError}
)

// dotnetHeader reads a .NET console header; its message follows on a later line.
func dotnetHeader(e Entry) (Record, bool) {
	m := dotnetHeaderLine.FindStringSubmatch(e.Message)
	if m == nil {
		return Record{}, false
	}
	return Record{Service: commService(e), Level: dotnetLevels[m[1]], Component: m[2]}, true
}

var (
	natsLine   = regexp.MustCompile(`^\[\d+\] \[(INF|WRN|ERR|FTL|DBG|TRC)\] (.*)`)
	natsLevels = map[string]string{"TRC": LevelDebug, "DBG": LevelDebug, "INF": LevelInfo, "WRN": LevelWarn, "ERR": LevelError, "FTL": LevelError}
	// A permission violation names its client and account; one cause is one class.
	violationQuote   = regexp.MustCompile(`"[^"]*"`)
	violationAccount = regexp.MustCompile(`\b(account|JWT)\s+\S+`)
)

// natsRecord reads an embedded NATS server line: "[pid] [WRN] text".
func natsRecord(e Entry) (Record, bool) {
	m := natsLine.FindStringSubmatch(e.Message)
	if m == nil {
		return Record{}, false
	}
	text := m[2]
	if strings.Contains(text, "Violation") {
		text = violationAccount.ReplaceAllString(violationQuote.ReplaceAllString(text, ""), "")
	}
	return Record{Service: "ts-orchestrator", Level: natsLevels[m[1]], Component: "nats", Message: Normalize(text), Example: example(e.Message)}, true
}

var (
	netbirdLine   = regexp.MustCompile(`^\S+ (TRAC|DEBU|INFO|WARN|ERRO|FATA|PANI) (?:\[[^\]]*\] )?(\S+?):\d+: (.*)$`)
	netbirdLevels = map[string]string{"TRAC": LevelDebug, "DEBU": LevelDebug, "INFO": LevelInfo, "WARN": LevelWarn, "ERRO": LevelError, "FATA": LevelError, "PANI": LevelError}
)

// netbirdRecord reads a NetBird client line: "time LEVEL [peer] file.go:line: text".
func netbirdRecord(e Entry) (Record, bool) {
	m := netbirdLine.FindStringSubmatch(e.Message)
	if m == nil {
		return Record{}, false
	}
	return Record{Service: "netbird", Level: netbirdLevels[m[1]], Component: m[2], Message: Normalize(m[3]), Example: example(e.Message)}, true
}

// priorityLevel maps the syslog PRIORITY: 0-3 error, 4 warning, 7 debug, the rest info.
func priorityLevel(priority string) string {
	n, err := strconv.Atoi(priority)
	switch {
	case err != nil:
		return LevelInfo
	case n <= 3:
		return LevelError
	case n == 4:
		return LevelWarn
	case n == 7:
		return LevelDebug
	}
	return LevelInfo
}

// unitService names a line by its systemd unit, or its process when it has none.
func unitService(e Entry) string {
	switch {
	case e.Comm == "systemd":
		return "systemd"
	case strings.HasPrefix(e.Unit, "terrascale-orchestrator"):
		return "ts-orchestrator"
	case e.Unit != "":
		return strings.TrimSuffix(e.Unit, ".service")
	}
	return commService(e)
}

// commService names a line by its process.
func commService(e Entry) string {
	switch {
	case strings.HasPrefix(e.Comm, "terrascale-orch"):
		return "ts-orchestrator"
	case e.Comm == "":
		return "unknown"
	}
	return e.Comm
}

func Normalize(message string) string {
	// The whole message is redacted before the cut: a cut first could leave half a credential.
	s := strings.TrimSpace(observability.RedactText(message, len(message)))
	for _, pattern := range []*regexp.Regexp{uuid, ulid, address, number} {
		s = pattern.ReplaceAllString(s, "N")
	}
	return cut(s, 160)
}

// example is the raw message a class keeps once, with its credentials redacted.
func example(message string) string {
	return observability.RedactText(strings.TrimSpace(message), 512)
}

// cut keeps at most n bytes of s without splitting a UTF-8 sequence.
func cut(s string, n int) string {
	if len(s) <= n {
		return s
	}
	for n > 0 && !utf8.RuneStart(s[n]) {
		n--
	}
	return s[:n]
}

func (s *logSanitizer) text(value string, limit int) string {
	// Fail closed rather than cutting an unfinished credential at the scan
	// boundary. All regex work is RE2 and limited to this input size.
	if len(value) > maxLogScanBytes {
		s.truncated = true
		return omittedLogValue
	}
	if !utf8.ValidString(value) {
		s.truncated = true
		value = strings.ToValidUTF8(value, "�")
	}
	value = logPEM.ReplaceAllString(value, redactedLogValue)
	value = logURL.ReplaceAllStringFunc(value, func(raw string) string {
		parsed, err := url.Parse(raw)
		if err != nil {
			return redactedLogValue
		}
		if parsed.User != nil {
			parsed.User = url.User(redactedLogValue)
		}
		return parsed.String()
	})
	value = logQuery.ReplaceAllStringFunc(value, func(raw string) string {
		key, _, _ := strings.Cut(raw[1:], "=")
		decoded, err := url.QueryUnescape(key)
		if err != nil || sensitiveLogKey(decoded) {
			return raw[:1] + key + "=" + redactedLogValue
		}
		return raw
	})
	value = logBearer.ReplaceAllString(value, "Bearer "+redactedLogValue)
	value = logJWT.ReplaceAllStringFunc(value, func(raw string) string {
		header, _, _ := strings.Cut(raw, ".")
		decoded, err := base64.RawURLEncoding.DecodeString(header)
		if err == nil && strings.HasPrefix(strings.TrimSpace(string(decoded)), "{") && json.Valid(decoded) {
			return redactedLogValue
		}
		return raw
	})
	value = logSeed.ReplaceAllString(value, redactedLogValue)
	if len(value) > limit {
		s.truncated = true
		cut := limit - len("...")
		for cut > 0 && !utf8.RuneStart(value[cut]) {
			cut--
		}
		value = value[:cut] + "..."
	}
	// Clone even short substrings: scoped strings must not pin large input buffers.
	return strings.Clone(value)
}

// RedactText applies the structured logger's credential redaction to value and
// keeps at most limit bytes. Text too large to scan becomes "[truncated]".
func RedactText(value string, limit int) string {
	s := logSanitizer{}
	return s.text(value, limit)
}

func startNATS(t *testing.T) *nats.Conn {
	t.Helper()
	srv, err := server.NewServer(&server.Options{Host: "127.0.0.1", Port: -1, JetStream: true,
		StoreDir: t.TempDir(), NoLog: true, NoSigs: true})
	if err != nil {
		t.Fatal(err)
	}
	go srv.Start()
	if !srv.ReadyForConnections(5 * time.Second) {
		t.Fatal("NATS did not start")
	}
	t.Cleanup(func() { srv.Shutdown(); srv.WaitForShutdown() })
	conn, err := nats.Connect(srv.ClientURL())
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(conn.Close)
	return conn
}

func publicUserKey(t *testing.T) string {
	t.Helper()
	pair, err := nkeys.CreateUser()
	if err != nil {
		t.Fatal(err)
	}
	public, err := pair.PublicKey()
	if err != nil {
		t.Fatal(err)
	}
	return public
}

func newLogPipeline(t *testing.T) *logPipeline {
	t.Helper()
	ctx, cancel := context.WithTimeout(t.Context(), 20*time.Second)
	t.Cleanup(cancel)
	conn := startNATS(t)
	js, err := jetstream.New(conn)
	if err != nil {
		t.Fatal(err)
	}
	stream, err := OpenStream(ctx, js, "gru", 1)
	if err != nil {
		t.Fatal(err)
	}
	p := &logPipeline{ctx: ctx, conn: conn, js: js, stream: stream, key: publicUserKey(t), barriers: NewCounter("gru", "barrier")}
	p.follow(t, NewView("gru"))
	return p
}

func (p *logPipeline) follow(t *testing.T, view *View) {
	t.Helper()
	p.view = view
	ctx, cancel := context.WithCancel(p.ctx)
	p.stop = cancel
	done := make(chan struct{})
	p.done = done
	go func() {
		defer close(done)
		p.stream.Follow(ctx, view, func(_ context.Context, node, key string) bool {
			return key == p.key && (strings.HasPrefix(node, "node-") || node == "barrier")
		})
	}()
	t.Cleanup(func() {
		cancel()
		select {
		case <-done:
		case <-time.After(3 * time.Second):
			t.Error("log follower did not stop")
		}
	})
	p.http = httptest.NewServer(Handler(view))
	p.http.Client().Timeout = 2 * time.Second
	t.Cleanup(p.http.Close)
}

func (p *logPipeline) publish(t *testing.T, key string, window Window) Window {
	t.Helper()
	data, err := json.Marshal(window)
	if err != nil {
		t.Fatal(err)
	}
	ack, err := p.js.Publish(p.ctx, protocol.AgentObservation("gru", key, "logs"), data)
	if err != nil {
		t.Fatal(err)
	}
	stored, err := p.stream.stream.GetMsg(p.ctx, ack.Sequence)
	if err != nil {
		t.Fatal(err)
	}
	var observed Window
	if err := json.Unmarshal(stored.Data, &observed); err != nil {
		t.Fatal(err)
	}
	return observed
}

func (p *logPipeline) get(t *testing.T, query string) Reply {
	t.Helper()
	req, err := http.NewRequestWithContext(p.ctx, http.MethodGet, p.http.URL+"/v1/logs?"+query, nil)
	if err != nil {
		t.Fatal(err)
	}
	response, err := p.http.Client().Do(req)
	if err != nil {
		t.Fatal(err)
	}
	defer response.Body.Close()
	data, err := io.ReadAll(io.LimitReader(response.Body, 2<<20))
	if err != nil {
		t.Fatal(err)
	}
	if response.StatusCode != http.StatusOK {
		t.Fatalf("log HTTP status %d: %s", response.StatusCode, data)
	}
	if response.Header.Get("Content-Type") != "application/json" || response.Header.Get("Cache-Control") != "no-store" {
		t.Fatalf("log response headers: %v", response.Header)
	}
	var reply Reply
	if err := json.Unmarshal(data, &reply); err != nil {
		t.Fatal(err)
	}
	return reply
}

// A streamed barrier proves earlier messages were processed before HTTP assertions.
func (p *logPipeline) sync(t *testing.T) {
	t.Helper()
	p.barriers.Add(Record{Service: "barrier", Level: LevelDebug, Message: "observed"})
	p.publish(t, p.key, p.barriers.Flush(time.Now().UTC().Truncate(time.Minute)))
	p.barrierCount++
	tick := time.NewTicker(5 * time.Millisecond)
	defer tick.Stop()
	for {
		reply := p.get(t, "service=barrier")
		if len(reply.Classes) == 1 && reply.Classes[0].Count == p.barrierCount {
			return
		}
		select {
		case <-p.ctx.Done():
			t.Fatalf("log stream barrier: %v; reply=%+v", p.ctx.Err(), reply)
		case <-tick.C:
		}
	}
}

func (p *logPipeline) query(t *testing.T, query string) Reply {
	t.Helper()
	p.sync(t)
	reply := p.get(t, query)
	reply.Classes = slices.DeleteFunc(reply.Classes, func(c ReplyClass) bool { return c.Service == "barrier" })
	reply.Totals = slices.DeleteFunc(reply.Totals, func(c Total) bool { return c.Service == "barrier" })
	return reply
}

func compareRecords(a, b Record) int {
	return strings.Compare(fmt.Sprint(a), fmt.Sprint(b))
}

func persistedWindow(t *testing.T, window Window) Window {
	t.Helper()
