func OpenStream(ctx context.Context, js jetstream.JetStream, cell string, replicas int) (*Stream, error) {
	if js == nil {
		return nil, errors.New("log summary stream requires JetStream")
	}
	subject := protocol.AgentObservation(cell, "*", "logs")
	if subject == "" {
		return nil, errors.New("log summary subject is invalid")
	}
	config := jetstream.StreamConfig{
		Name:        StreamName,
		Description: "Regional log summary windows",
		Subjects:    []string{subject},
		Storage:     jetstream.FileStorage,
		Replicas:    replicas,
		Retention:   jetstream.LimitsPolicy,
		Discard:     jetstream.DiscardOld,
		MaxAge:      streamMaxAge,
		MaxBytes:    streamBytes,
		MaxMsgs:     -1,
		MaxMsgSize:  maxMessageBytes,
	}
	stream, err := js.CreateStream(ctx, config)
	if errors.Is(err, jetstream.ErrStreamNameAlreadyInUse) {
		stream, err = js.UpdateStream(ctx, config)
	}
	if err != nil {
		return nil, fmt.Errorf("open log summary stream: %w", err)
	}
	return &Stream{stream: stream}, nil
}

// Follow feeds view from the stream until ctx ends. It starts 24 hours back, so
// a restart or leader change rebuilds the view, and the view skips windows it
// already counted. verify must confirm that node is registered with nkey.
func (stream *Stream) Follow(ctx context.Context, view *View, verify func(ctx context.Context, node, nkey string) bool) {
	verdicts := &verdictCache{verify: verify, verdicts: make(map[nodeKey]verdict)}
	delay := retryFirst
	failing := false
	for {
		ctx := observability.StartTrace(ctx)
		started := time.Now()
		ready, err := stream.run(ctx, view, verdicts)
		if ready && failing {
			slog.InfoContext(ctx, "log summary follower recovered", observability.ComponentKey, "logs")
			failing = false
		}
		if ctx.Err() != nil {
			return
		}
		if failing {
			slog.DebugContext(ctx, "log summary follower still failing", observability.ComponentKey, "logs", "error", err)
		} else {
			slog.WarnContext(ctx, "log summary follower failed; retrying", observability.ComponentKey, "logs", "error", err)
			failing = true
		}
		// A consumer that lasted a while was healthy: its next failure starts over.
		if time.Since(started) >= retryMax {
			delay = retryFirst
		}
		select {
		case <-ctx.Done():
			return
		case <-time.After(delay):
		}
		delay = min(2*delay, retryMax)
	}
}

// run follows the stream until the consumer fails or ctx ends. ready reports
// whether the consumer was created.
func (stream *Stream) run(ctx context.Context, view *View, verdicts *verdictCache) (bool, error) {
	start := time.Now().Add(-retention)
	consumer, err := stream.stream.OrderedConsumer(ctx, jetstream.OrderedConsumerConfig{
		DeliverPolicy: jetstream.DeliverByStartTimePolicy,
		OptStartTime:  &start,
	})
	if err != nil {
		return false, err
	}
	messages, err := consumer.Messages()
	if err != nil {
		return true, err
	}
	defer messages.Stop()
	stop := context.AfterFunc(ctx, messages.Stop)
	defer stop()
	for {
		msg, err := messages.Next()
		if err != nil {
			return true, err
		}
		accept(ctx, msg, view, verdicts)
	}
}

// accept counts one window whose node is verified for the NKey in its subject.
// A malformed or unverified window is dropped.
func accept(ctx context.Context, msg jetstream.Msg, view *View, verdicts *verdictCache) {
	var window Window
	if protocol.DecodeStrict(msg.Data(), &window, maxWindowBytes) != nil || window.Version != 1 {
		return
	}
	// The subject is ts.orch.v1.<cell>.agent.<nkey>.observation.logs.
	tokens := strings.Split(msg.Subject(), ".")
	if len(tokens) < 3 || !verdicts.allowed(ctx, window.Node, tokens[len(tokens)-3]) {
		return
	}
	view.Add(window, time.Now())
}

type nodeKey struct{ node, nkey string }

type verdict struct {
	ok bool
	at time.Time
}

// verdictCache remembers each node's verdict for verdictTTL, so a replay asks
// the registration once per node and key rather than once per window.
type verdictCache struct {
	verify   func(ctx context.Context, node, nkey string) bool
	verdicts map[nodeKey]verdict
}

func (c *verdictCache) allowed(ctx context.Context, node, nkey string) bool {
	key := nodeKey{node, nkey}
	if v, ok := c.verdicts[key]; ok && time.Since(v.at) < verdictTTL {
		return v.ok
	}
	ok := c.verify(ctx, node, nkey)
	c.verdicts[key] = verdict{ok: ok, at: time.Now()}
	return ok
}

func Regional(cell string, tokens ...string) string {
	root, err := RegionalRoot(cell)
	if err != nil {
		return ""
	}
	return joinSubject(root, tokens)
}

func AgentObservation(cell, agent, observation string) string {
	return Regional(cell, "agent", agent, "observation", observation)
}

func joinSubject(root string, tokens []string) string {
	if len(tokens) == 0 {
		return root
	}
	var builder strings.Builder
	builder.WriteString(root)
	for index, token := range tokens {
		for part := range strings.SplitSeq(token, ".") {
			if !validFamilyToken(part, index == len(tokens)-1) {
				return ""
			}
		}
		builder.WriteByte('.')
		builder.WriteString(token)
	}
	result := builder.String()
	// ">" may only terminate the whole subject.
	if index := strings.Index(result, ">"); index >= 0 && index != len(result)-1 {
		return ""
	}
	return result
}

func RegionalRoot(region string) (string, error) {
	token, err := RegionToken(region)
	if err != nil || token == GlobalScope {
		return "", ErrInvalidSubjectToken
	}
	return SubjectRoot + "." + token, nil
}

func NewCounter(region, node string) *Counter {
	return &Counter{region: region, node: node, boot: entityid.New(), classes: make(map[Class]tally)}
}

// Add counts one record in the minute being counted. A class keeps the example of its first record.
func (c *Counter) Add(r Record) {
	key := Class{Service: r.Service, Level: r.Level, Component: r.Component, Message: r.Message}
	t, seen := c.classes[key]
	if !seen {
		t.example = r.Example
	}
	t.count++
	c.classes[key] = t
}

// Flush ends a minute and returns its window. The window keeps the most frequent
// classes and counts the rest as dropped; the counter starts the next minute empty.
func (c *Counter) Flush(minute time.Time) Window {
	classes := make([]Class, 0, len(c.classes))
	for key, t := range c.classes {
		key.Count, key.Example = t.count, t.example
		classes = append(classes, key)
	}
	clear(c.classes)
	slices.SortFunc(classes, compareClasses)
	window := Window{Version: 1, Region: c.region, Node: c.node, Minute: minute.UTC(), Boot: c.boot, Seq: c.seq, Classes: classes}
	c.seq++
	if len(classes) > maxClasses {
		window.Dropped = sumCounts(classes[maxClasses:])
		window.Classes = classes[:maxClasses]
	}
	for encodedLen(window) > maxWindowBytes {
		last := len(window.Classes) - 1
		window.Dropped += window.Classes[last].Count
		window.Classes = window.Classes[:last]
	}
	return window
}

// compareClasses puts the most frequent first. Ties go to the more severe level, then to text.
func compareClasses(a, b Class) int {
	return cmp.Or(cmp.Compare(b.Count, a.Count), cmp.Compare(severity(b.Level), severity(a.Level)),
		cmp.Compare(a.Service, b.Service), cmp.Compare(a.Component, b.Component), cmp.Compare(a.Message, b.Message))
}

func sumCounts(classes []Class) int {
	total := 0
	for _, class := range classes {
		total += class.Count
	}
	return total
}

// encodedLen is the window's JSON size. Marshal cannot fail: every field is a string or a number.
func encodedLen(window Window) int {
	data, _ := json.Marshal(window)
	return len(data)
}

func NewView(region string) *View {
	return &View{region: region, classes: make(map[Class]*classStats), seqs: make(map[nodeBoot]seqState)}
}

// Add counts one node window at now. A window older than the retention, or one
// the view already counted, is ignored: a replay after a restart delivers both.
func (v *View) Add(w Window, now time.Time) {
	v.mu.Lock()
	defer v.mu.Unlock()
	if w.Minute.Before(now.Add(-retention)) || !v.track(w, now) {
		return
	}
	for _, c := range w.Classes {
		key := Class{Service: c.Service, Level: c.Level, Component: c.Component, Message: c.Message}
		stats, ok := v.classes[key]
		if !ok {
			stats = v.admit()
			v.classes[key] = stats
		}
		stats.add(w.Node, w.Minute, c)
	}
}

// track reports whether w is new within its boot and counts the sequence gap it reveals.
func (v *View) track(w Window, now time.Time) bool {
	if now.Sub(v.pruned) >= time.Hour {
		v.pruned = now
		for key, state := range v.seqs {
			if state.seen.Before(now.Add(-retention)) {
				delete(v.seqs, key)
			}
		}
	}
	key := nodeBoot{w.Node, w.Boot}
	last, seen := v.seqs[key]
	if seen && w.Seq <= last.seq {
		return false
	}
	if seen && w.Seq > last.seq+1 {
		v.gaps += int(w.Seq - last.seq - 1)
	}
	v.seqs[key] = seqState{seq: w.Seq, seen: now}
	return true
}

// admit makes room for a new class. A full region evicts the class seen least recently.
func (v *View) admit() *classStats {
	if len(v.classes) >= maxClassKeys {
		var oldest Class
		var oldestStats *classStats
		for key, stats := range v.classes {
			if oldestStats == nil || stats.last.Before(oldestStats.last) {
				oldest, oldestStats = key, stats
			}
		}
		delete(v.classes, oldest)
		v.evicted++
	}
	return &classStats{nodes: make(map[string]struct{})}
}

func (s *classStats) add(node string, minute time.Time, c Class) {
	if s.first.IsZero() || minute.Before(s.first) {
		s.first = minute
	}
	if !minute.Before(s.last) {
		s.last, s.example = minute, c.Example
	}
	if len(s.nodes) < maxNodesPerClass {
		s.nodes[node] = struct{}{}
	}
	addBucket(s.minutes[:], minute.Unix()/60, c.Count)
	addBucket(s.hours[:], minute.Unix()/3600, c.Count)
}

// count is the class's records in the window that ends at now.
func (s *classStats) count(window string, now time.Time) int {
	if window == "24h" {
		return sumBuckets(s.hours[:], now.Unix()/3600)
	}
	return sumBuckets(s.minutes[:], now.Unix()/60)
}

func (s *classStats) reply(class Class) ReplyClass {
	nodes := make([]string, 0, len(s.nodes))
	for node := range s.nodes {
		nodes = append(nodes, node)
	}
	slices.Sort(nodes)
	return ReplyClass{Service: class.Service, Level: class.Level, Component: class.Component, Message: class.Message,
		Count: class.Count, Nodes: nodes, First: s.first, Last: s.last, Example: s.example}
}

// addBucket counts into its period's slot. A period older than the slot's is
// outside the ring, so its count is dropped.
func addBucket(slots []bucket, period int64, count int) {
	slot := &slots[period%int64(len(slots))]
	if slot.period < period {
		*slot = bucket{period: period}
	}
	if slot.period == period {
		slot.count += count
	}
}

// sumBuckets totals the periods of the ring that end at now.
func sumBuckets(slots []bucket, now int64) int {
	total := 0
	for _, slot := range slots {
		if slot.period > now-int64(len(slots)) && slot.period <= now {
			total += slot.count
		}
	}
	return total
}

// Validate reports whether the query serves the request.
func (r Request) Validate() error {
	switch {
	case r.Version != 1:
		return errors.New("version must be 1")
	case r.Window != "1h" && r.Window != "24h":
		return errors.New("window must be 1h or 24h")
	case !validLevel(r.MinLevel):
		return errors.New("min_level must be DEBUG, INFO, WARN or ERROR")
	case r.Limit < 0 || r.Limit > maxLimit:
		return errors.New("limit must be from 0 to 500")
	case len(r.Service) > maxServiceBytes:
		return errors.New("service must be at most 64 bytes")
	}
	return nil
}

func (r Request) keeps(class Class) bool {
	return severity(class.Level) >= severity(r.MinLevel) && (r.Service == "" || class.Service == r.Service)
}

// Summary answers req as of now. Totals cover every matching class; the classes
// are the most frequent up to the limit.
func (v *View) Summary(req Request, now time.Time) Reply {
	v.mu.Lock()
	defer v.mu.Unlock()
	reply := Reply{Version: 1, Region: v.region, From: windowStart(req.Window, now), To: now.UTC(), Gaps: v.gaps,
		Totals: []Total{}, Classes: []ReplyClass{}}
	totals := make(map[[2]string]int)
	var hits []hit
	for key, stats := range v.classes {
		if !req.keeps(key) {
			continue
		}
		count := stats.count(req.Window, now)
		if count == 0 {
			continue
		}
		key.Count = count
		totals[[2]string{key.Service, key.Level}] += count
		hits = append(hits, hit{key, stats})
	}
	for pair, count := range totals {
		reply.Totals = append(reply.Totals, Total{Service: pair[0], Level: pair[1], Count: count})
	}
	slices.SortFunc(reply.Totals, compareTotals)
	slices.SortFunc(hits, func(a, b hit) int { return compareClasses(a.Class, b.Class) })
	limit := min(cmp.Or(req.Limit, defaultLimit), maxLimit)
	if len(hits) > limit {
		hits = hits[:limit]
		reply.Truncated = true
	}
	for _, h := range hits {
		reply.Classes = append(reply.Classes, h.stats.reply(h.Class))
	}
	return reply
}

// Errors returns the most frequent WARN and ERROR classes of the last hour, for
// the global rollup. It does no I/O.
func (v *View) Errors(limit int, now time.Time) []ReplyClass {
	return v.Summary(Request{Version: 1, Window: "1h", MinLevel: LevelWarn, Limit: limit}, now).Classes
}

// windowStart is the first instant of the window: 59 minutes back for "1h", 23 hours back for "24h".
func windowStart(window string, now time.Time) time.Time {
	if window == "24h" {
		return now.Truncate(time.Hour).Add(-23 * time.Hour).UTC()
	}
	return now.Truncate(time.Minute).Add(-59 * time.Minute).UTC()
}

func compareTotals(a, b Total) int {
	return cmp.Or(cmp.Compare(a.Service, b.Service), cmp.Compare(severity(a.Level), severity(b.Level)))
}

func Serve(ctx context.Context, conn *nats.Conn, cell string, view *View) (*nats.Subscription, error) {
	if conn == nil || view == nil {
		return nil, errors.New("log query responder requires a connection and a view")
	}
	subject := protocol.Regional(cell, "query", "logs.v1")
	if subject == "" {
		return nil, errors.New("log query subject is invalid")
	}
	subscription, err := conn.QueueSubscribe(subject, "logs", func(message *nats.Msg) {
		if message.Reply == "" {
			return
		}
		_ = message.Respond(answer(view, message.Data, conn.MaxPayload(), time.Now()))
	})
	if err != nil {
		return nil, err
	}
	context.AfterFunc(ctx, func() { _ = subscription.Unsubscribe() })
	return subscription, nil
}

// answer encodes the reply to one request. A reply larger than the connection's
// payload keeps the most frequent classes that fit and is marked truncated.
func answer(view *View, data []byte, maxPayload int64, now time.Time) []byte {
	var request Request
	if protocol.DecodeStrict(data, &request, maxRequestBytes) != nil || request.Validate() != nil {
		return invalidRequest
	}
	reply := view.Summary(request, now)
	for {
		encoded, err := json.Marshal(reply)
		if err != nil {
			return invalidRequest
		}
		if int64(len(encoded)) <= maxPayload || len(reply.Classes) == 0 {
			return encoded
		}
		reply.Classes = reply.Classes[:len(reply.Classes)/2]
		reply.Truncated = true
	}
}

// Handler serves GET /v1/logs on the private listener with the same reply as
// query.logs.v1, for this region. Missing parameters take the defaults.
func Handler(view *View) http.Handler {
	return http.HandlerFunc(func(writer http.ResponseWriter, request *http.Request) {
		params := request.URL.Query()
		req := Request{Version: 1, Window: cmp.Or(params.Get("window"), "1h"),
			MinLevel: cmp.Or(params.Get("min_level"), LevelDebug), Service: params.Get("service")}
		if params.Has("limit") {
			limit, err := strconv.Atoi(params.Get("limit"))
			if err != nil {
				http.Error(writer, "limit must be a number", http.StatusBadRequest)
				return
			}
			req.Limit = limit
		}
		if err := req.Validate(); err != nil {
			http.Error(writer, err.Error(), http.StatusBadRequest)
			return
		}
		writer.Header().Set("Content-Type", "application/json")
		writer.Header().Set("Cache-Control", "no-store")
		_ = json.NewEncoder(writer).Encode(view.Summary(req, time.Now()))
	})
}
